output_text:
[
  {
    "id": "no_cart_in_single_file_corridor",
    "text": "Shopping carts are prohibited in one-person-width horizontal passages.",
    "abstraction": {
      "state_properties": {
        "onePersonWidth": {
          "le": [
            "freeWidthH",
            2
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "onePersonWidth"
        ]
      }
    }
  },
  {
    "id": "no_cart_between_opposing_shelves",
    "text": "A cart must not be taken into a narrow aisle where shelves are immediately on both sides.",
    "abstraction": {
      "state_properties": {
        "opposingShelfAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "opposingShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_shelf_canyon",
    "text": "Customers may not move into a single-file shelf aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "shelfCanyon": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterShelfCanyon": {
          "pre": "MOVE",
          "post": "shelfCanyon"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "enterShelfCanyon"
        ]
      }
    }
  },
  {
    "id": "park_cart_at_canyon_mouth",
    "text": "On arriving with a cart at the mouth of a single-file shelf aisle, the customer is obliged to park the cart there before proceeding.",
    "abstraction": {
      "state_properties": {
        "cartBay": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "canyonMouth": {
          "and": [
            "at(3,3)",
            "cartBay"
          ]
        }
      },
      "events": {
        "arriveAtCanyonMouthWithCart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": "canyonMouth"
        },
        "dropCartAtMouth": {
          "pre": {
            "and": [
              "canyonMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arriveAtCanyonMouthWithCart",
      "discharge": "dropCartAtMouth"
    }
  },
  {
    "id": "drop_cart_only_in_open_bay",
    "text": "Carts may only be parked or released in a broad open bay, not inside shelf aisles or constricted passages.",
    "abstraction": {
      "state_properties": {
        "openCartBay": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "openCartBay"
          }
        ]
      }
    }
  },
  {
    "id": "shelf_interaction_on_foot",
    "text": "Shelf interactions in a single-file shelf aisle must be performed without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "INTERACT",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_narrow_aisle",
    "text": "After leaving a single-file shelf aisle back into its open mouth, the customer is obliged to retrieve the parked cart.",
    "abstraction": {
      "state_properties": {
        "shelfCanyon": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "canyonMouth": {
          "and": [
            "at(3,3)",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "leaveCanyonToMouth": {
          "pre": {
            "and": [
              "shelfCanyon",
              "MOVE"
            ]
          },
          "post": "canyonMouth"
        },
        "pickupCartAtMouth": {
          "pre": {
            "and": [
              "canyonMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "leaveCanyonToMouth",
      "discharge": "pickupCartAtMouth"
    }
  },
  {
    "id": "no_walking_main_aisles_without_cart",
    "text": "Away from the entrance and the cart-parking mouth, customers should not walk through broad main aisles without their cart.",
    "abstraction": {
      "state_properties": {
        "broadMainAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "exemptCartPoint": {
          "or": [
            "at(0,7)",
            "at(3,3)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "broadMainAisle",
          {
            "not": "exemptCartPoint"
          },
          {
            "not": "hasCart"
          },
          "MOVE"
        ]
      }
    }
  }
]
